/**
 * P6-f dev-time generator: extracts the Standard-14 AFM metrics (widths,
 * kern pairs) and the WinAnsi unicode mapping from @pdf-lib/standard-fonts —
 * the EXACT data pdf-lib itself uses — and freezes them into
 * src/lib/own/pdf/stamp-fonts.ts so our own engine ships pdf-lib-identical
 * text measurement with zero runtime dependency.
 *
 * Run: bun scripts/gen-stamp-fonts.ts
 * (Not part of any build/gate — the generated file is committed.)
 */

import { writeFileSync } from "node:fs";
import { Font, FontNames, Encodings } from "@pdf-lib/standard-fonts";

const TARGETS: Array<{ id: string; fontName: FontNames }> = [
  { id: "helvetica", fontName: FontNames.Helvetica },
  { id: "helveticaBold", fontName: FontNames.HelveticaBold },
  { id: "helveticaOblique", fontName: FontNames.HelveticaOblique },
  { id: "helveticaBoldOblique", fontName: FontNames.HelveticaBoldOblique },
  { id: "times", fontName: FontNames.TimesRoman },
  { id: "timesBold", fontName: FontNames.TimesRomanBold },
  { id: "timesItalic", fontName: FontNames.TimesRomanItalic },
  { id: "timesBoldItalic", fontName: FontNames.TimesRomanBoldItalic },
  { id: "courier", fontName: FontNames.Courier },
  { id: "courierBold", fontName: FontNames.CourierBold },
  { id: "courierOblique", fontName: FontNames.CourierOblique },
  { id: "courierBoldOblique", fontName: FontNames.CourierBoldOblique },
];

interface GenFont {
  base: string;
  /** WinAnsi code → glyph width (1000 units/em); -1 = no glyph at that code. */
  widths: number[];
  /** "leftGlyph|rightGlyph" → kern amount (1000 units/em). */
  kern: Record<string, number>;
}

const fonts: Record<string, GenFont> = {};
let problems = 0;

for (const { id, fontName } of TARGETS) {
  const font = Font.load(fontName as never) as unknown as {
    FontName: string;
    CharMetrics: Array<{ C: number; WX: number; N: string }>;
    KernPairs: Array<[string, string, number]>;
    MissingWidth?: number;
  };
  const widthByName = new Map<string, number>();
  for (const metric of font.CharMetrics) widthByName.set(metric.N, metric.WX);

  const widths = new Array<number>(256).fill(-1);
  const glyphByCode = new Map<number, string>();
  const winAnsi = Encodings.WinAnsi as unknown as {
    supportedCodePoints: number[];
    encodeUnicodeCodePoint(cp: number): { code: number; name: string };
  };
  for (const cp of winAnsi.supportedCodePoints) {
    const { code, name } = winAnsi.encodeUnicodeCodePoint(cp);
    glyphByCode.set(code, name);
    const w = widthByName.get(name) ?? font.MissingWidth ?? -1;
    if (w < 0) {
      console.error(`!! ${id}: glyph "${name}" (cp U+${cp.toString(16)}) has no width`);
      problems += 1;
    }
    widths[code] = w;
  }

  const kern: Record<string, number> = {};
  for (const [n1, n2, amount] of font.KernPairs) kern[`${n1}|${n2}`] = amount;

  fonts[id] = { base: font.FontName, widths, kern };
}

// WinAnsi unicode → (code, glyphName) map (encoding side, font-independent).
const winAnsiMap: Array<[number, number, string]> = [];
{
  const winAnsi = Encodings.WinAnsi as unknown as {
    supportedCodePoints: number[];
    encodeUnicodeCodePoint(cp: number): { code: number; name: string };
  };
  for (const cp of winAnsi.supportedCodePoints) {
    const { code, name } = winAnsi.encodeUnicodeCodePoint(cp);
    winAnsiMap.push([cp, code, name]);
  }
}

if (problems > 0) {
  console.error(`${problems} metric problems — NOT writing the generated file`);
  process.exit(1);
}

const lines: string[] = [];
lines.push("/**");
lines.push(" * DocoPDF own PDF micro-engine — Standard-14 stamp metrics (P6-f).");
lines.push(" *");
lines.push(" * GENERATED by scripts/gen-stamp-fonts.ts from @pdf-lib/standard-fonts");
lines.push(" * AFM data (widths + kern pairs) and the WinAnsi encoding table — the exact");
lines.push(" * numbers pdf-lib's StandardFontEmbedder uses — so measureStdText() is");
lines.push(" * pdf-lib-identical byte for byte. Do not edit by hand; regenerate instead.");
lines.push(" */");
lines.push("");
lines.push("export type StampFontKey =");
for (const { id } of TARGETS) lines.push(`  | "${id}"`);
lines.push("  ;");
lines.push("");
lines.push("export interface StdFontMetrics {");
lines.push("  /** PDF /BaseFont name (e.g. \"Helvetica-Bold\"). */");
lines.push("  base: string;");
lines.push("  /** WinAnsi code (0..255) → glyph width in 1000 units/em; -1 = no glyph. */");
lines.push("  widths: number[];");
lines.push("  /** \"leftGlyph|rightGlyph\" → kern amount in 1000 units/em. */");
lines.push("  kern: Record<string, number>;");
lines.push("}");
lines.push("");
lines.push("export const STD_FONTS: Record<StampFontKey, StdFontMetrics> = {");
for (const { id } of TARGETS) {
  const f = fonts[id]!;
  lines.push(`  ${id}: {`);
  lines.push(`    base: ${JSON.stringify(f.base)},`);
  lines.push(
    `    widths: [${f.widths.join(",")}],`,
  );
  const kernEntries = Object.entries(f.kern);
  if (kernEntries.length === 0) {
    lines.push(`    kern: {},`);
  } else {
    lines.push(`    kern: {`);
    for (const [pair, amount] of kernEntries) {
      lines.push(`      ${JSON.stringify(pair)}: ${amount},`);
    }
    lines.push(`    },`);
  }
  lines.push(`  },`);
}
lines.push("};");
lines.push("");
lines.push("/** Unicode code point → WinAnsi byte (the encodable subset). */");
lines.push(
  `export const WIN_ANSI_CODE: Map<number, number> = new Map([${winAnsiMap
    .map(([cp, code]) => `[${cp},${code}]`)
    .join(",")}]);`,
);
lines.push("");
lines.push(
  "/** WinAnsi byte → PDF glyph name (kern-table keys; Adobe canonical). */",
);
lines.push(
  `export const WIN_ANSI_NAME: Map<number, string> = new Map([${winAnsiMap
    .map(([cp, code, name]) => `[${code},${JSON.stringify(name)}]`)
    .join(",")}]);`,
);
lines.push("");

writeFileSync("src/lib/own/pdf/stamp-fonts-data.ts", lines.join("\n"));
console.log(
  `Wrote src/lib/own/pdf/stamp-fonts-data.ts — ${TARGETS.length} fonts, ` +
    `winAnsi codes: ${winAnsiMap.length}, ` +
    `kern pairs: ${Object.values(fonts).reduce((n, f) => n + Object.keys(f.kern).length, 0)}`,
);
